import { Pressable, Text, View } from 'react-native';
import { useTranslation } from 'react-i18next';
import * as WebBrowser from 'expo-web-browser';
import { SettingsPage } from '@/components/settings/settingsKit';
import licenses from '@/constants/licenses.json';
import { fontFamily, useTheme } from '@/theme';

type License = { name: string; version: string; license: string; url: string | null };

/** Open-source packages shipped in the app, generated by `npm run licenses`. */
export default function LicensesScreen() {
  const { t } = useTranslation();
  const theme = useTheme();
  return (
    <SettingsPage title={t('about.licenses')} subtitle={t('about.licensesIntro')}>
      <View style={{ backgroundColor: theme.colors.card, borderRadius: 18, overflow: 'hidden' }}>
        {(licenses as License[]).map((item, index) => (
          <Pressable
            key={item.name}
            accessibilityRole={item.url ? 'link' : undefined}
            disabled={!item.url}
            onPress={() => item.url && void WebBrowser.openBrowserAsync(item.url)}
            style={({ pressed }) => ({
              paddingHorizontal: 16,
              paddingVertical: 12,
              gap: 2,
              borderTopWidth: index === 0 ? 0 : 1,
              borderTopColor: theme.colors.hairline,
              backgroundColor: pressed ? theme.colors.field : 'transparent',
            })}>
            <Text style={{ fontFamily: fontFamily.interMedium, fontSize: 14, color: theme.colors.textPrimary }}>{item.name}</Text>
            <Text style={{ fontFamily: fontFamily.interRegular, fontSize: 12.5, color: theme.colors.textTertiary }}>
              {item.version} · {item.license}
            </Text>
          </Pressable>
        ))}
      </View>
    </SettingsPage>
  );
}
